<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\BelongsToMany;use Illuminate\Database\Eloquent\Relations\HasMany;
final class InsuranceProduct extends Model{use HasUuids;protected$fillable=['carrier_id','line_code','code','name','version','effective_from','effective_until','status','coverages','eligibility_rules','created_by','published_by','published_at','regulatory_reference'];protected function casts():array{return['effective_from'=>'date','effective_until'=>'date','coverages'=>'array','eligibility_rules'=>'array','published_at'=>'datetime'];}public function carrier():BelongsTo{return$this->belongsTo(Carrier::class);}public function coverageDefinitions():BelongsToMany{return$this->belongsToMany(CoverageDefinition::class,'product_coverages')->withPivot(['default_limit_minor','default_deductible_minor','configuration','is_optional','display_order']);}public function exclusions():BelongsToMany{return$this->belongsToMany(ExclusionDefinition::class,'product_exclusions')->withPivot('configuration');}public function tariffs():HasMany{return$this->hasMany(TariffVersion::class);}}
